.pos { color: var(--pos); }
.neg { color: var(--neg); }

button.delete {
  background: transparent;
  color: var(--neg);
  border-color: transparent;
  padding: 2px 8px;
}

button.delete:hover { border-color: var(--neg); }

.empty { color: var(--muted); text-align: center; margin: 16px 0; }

canvas#chart {
  display: block;
  width: 100%;
  height: 260px;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

@media (max-width: 720px) {
  form { grid-template-columns: 1fr 1fr; }
  form button { grid-column: span 2; }
  .totals { grid-template-columns: 1fr; }
}

